#!/bin/bash
###############################################################################
# Removes a marked block from a hosts file. Source this file; it runs nothing.
#
# Writes in place, never sed -i or a rename: /etc/hosts is a bind mount inside the
# node agent's sandbox, and replacing the file outside takes that mount away from the
# running agent. Markers are whole lines, and a start marker with no end removes the
# marker and the entries directly below it, not the rest of the file.
#
# The client script generated by setup-local-dns.sh runs on other machines, so it
# carries its own copy of the filter.
###############################################################################

# hosts_without_block <file> <begin-marker> <end-marker>: prints the file without it.
hosts_without_block() {
    HOSTS_BEGIN="$2" HOSTS_END="$3" LC_ALL=C awk '
        function trimmed(text) { gsub(/^[ \t]+|[ \t\r]+$/, "", text); return text }
        function block_entry(text,    f, n, k) {
            n = split(text, f)
            if (n < 2 || f[1] !~ /^[0-9A-Fa-f:.]+$/) return 0
            for (k = 2; k <= n; k++) if (f[k] !~ /\.local$/) return 0
            return 1
        }
        BEGIN { begin_marker = ENVIRON["HOSTS_BEGIN"]; end_marker = ENVIRON["HOSTS_END"] }
        { line[NR] = $0 }
        END {
            for (i = 1; i <= NR; i++) {
                text = trimmed(line[i])
                if (text == end_marker) continue
                if (text == begin_marker) {
                    stop = 0
                    for (j = i + 1; j <= NR; j++) {
                        text = trimmed(line[j])
                        if (text == end_marker) { stop = j; break }
                        if (text == begin_marker) break
                    }
                    if (stop) i = stop
                    else while (i < NR && block_entry(line[i + 1])) i++
                    continue
                }
                print line[i]
            }
        }
    ' "$1"
}

# hosts_write_in_place <new-contents-file> <hosts-file>
# Puts the old contents back if the write fails or doesn't take.
hosts_write_in_place() {
    local new="$1" file="$2" old status=0
    old=$(mktemp) || return 1
    if ! cat "$file" >"$old"; then
        rm -f "$old"
        return 1
    fi
    if ! { hosts_replace_contents "$new" "$file" && cmp -s "$new" "$file"; } 2>/dev/null; then
        hosts_replace_contents "$old" "$file" 2>/dev/null || true
        status=1
    fi
    rm -f "$old"
    return "$status"
}

hosts_replace_contents() {
    if [[ -w "$2" ]]; then
        cat "$1" >"$2"
    else
        sudo tee "$2" <"$1" >/dev/null
    fi
}

# hosts_remove_block <file> <begin-marker> <end-marker>
hosts_remove_block() {
    local file="$1" new status=0
    new=$(mktemp) || return 1
    if ! hosts_without_block "$file" "$2" "$3" >"$new"; then
        status=1
    elif ! cmp -s "$new" "$file"; then
        hosts_write_in_place "$new" "$file" || status=1
    fi
    rm -f "$new"
    return "$status"
}
